struct Credentials { std::string scheme; std::string blob; };

struct Authenticator {
    virtual ~Authenticator() = default;
    virtual std::shared_ptr<Principal> authenticate(const Credentials&) const = 0;
};

using Factory = std::function<std::unique_ptr<Authenticator>()>;
std::unordered_map<std::string, Factory> make_registry(UserStore& users, Jwks& jwks, const std::string& issuer) {
    return {
        {"password", [&users] { return std::unique_ptr<Authenticator>(new PasswordAuthenticator(users)); }},
        {"bearer",   [&jwks, &issuer] { return std::unique_ptr<Authenticator>(new JwtAuthenticator(jwks, issuer)); }},
    };
}
